package com.cenedu.backend.domain.problem.authoring.diagram;
import static org.assertj.core.api.Assertions.*; import java.util.*; import org.junit.jupiter.api.Test;
class DiagramSpecValidatorTest { private final DiagramSpecValidator v=new DiagramSpecValidator(); private DiagramStyle style(){return new DiagramStyle("#000000","#FFFFFF","#FF0000",1,"sans-serif",12);} private DiagramViewport view(){return new DiagramViewport(400,300,16);} @Test void rejectsExternalMarkupInLabels(){var d=new NumberLineDiagramSpecV1(1,"LINE",DiagramKind.NUMBER_LINE,view(),style(),"MIN","MAX","STEP",List.of(new NumberLinePointSpec("P","X","<script src=https://x>",PointMarker.CLOSED_CIRCLE)),List.of(),false,false);assertThatThrownBy(()->v.validate(d,Map.of())).isInstanceOf(DiagramValidationException.class);} }
